1	// tabitisrael.co.il reservation pages — Tabit is the online-reservation system
2	// many Israeli restaurants use. The supported page is a single saved booking's
3	// summary, e.g.
4	//   https://tabitisrael.co.il/.../create-reservation?step=summary&reservationId=...
5	//
6	// It's an Angular single-page app, so this works against the RENDERED DOM (the
7	// committed fixture is a browser outerHTML capture, not the empty index shell —
8	// a plain fetch of the URL is CloudFront-bot-blocked, see issue #345). The page
9	// embeds schema.org JSON-LD, but it's a `Restaurant`, not an `Event` (no date),
10	// so GCal.embeddedEvents can't help — every field is read straight from the DOM.
11	//
12	// Where each field comes from (rendered markup):
13	//   title       <organization-details> ._sub_title  ("Meatbar TLV")
14	//   location    title + ._address                   ("…, שדרות חן 52, תל אביב")
15	//   start       .reservation-details-item .value for the rsv-date + rsv-time
16	//               icons ("א׳ 21/6" + "12:00"). The displayed date has NO YEAR, so
17	//               the year is inferred as the nearest upcoming one (a reservation
18	//               is in the future) off GCal.now() — injectable in tests so the
19	//               asserted date can't rot.
20	//   end         not shown on the page -> omitted (single start time only)
21	//   description .description block (the saved-reservation confirmation message,
22	//               multi-line — blockText preserves its <br> line breaks)
23	//   ctz         hardcoded Asia/Jerusalem (every Tabit venue is in Israel)
24	//
25	// This source states every field itself, not because it has to — the core
26	// generic extractor runs underneath it like anywhere else — but because there is
27	// nothing for that base to read here: the page's only JSON-LD is a `Restaurant`,
28	// so it carries no event, no date, and no og: event metadata.
29	(() => {
30	  const { text, blockText } = GCal;
31	  const pad = (n) => String(n).padStart(2, "0");
32	
33	  // The summary lists date / time / guests as sibling .reservation-details-item
34	  // blocks, each an icon (mat-icon[svgicon="rsv-…"]) plus a .value. Read by icon
35	  // name rather than a positional/secondary class so reordering can't misread.
36	  function detailValue(icon) {
37	    const el = document.querySelector(`[svgicon="${icon}"]`);
38	    const item = el && el.closest(".reservation-details-item");
39	    return item ? text(".value", item) : "";
40	  }
41	
42	  // Build "YYYY-MM-DDTHH:MM:00" (floating local time; ctz places it) from the
43	  // page's "<day-of-week> D/M" date and "HH:MM" time. The year is absent on the
44	  // page, so pick the nearest upcoming year for that day/month. Uses UTC
